// Cmd+1 = Go Back (same as Alt+Left / workbench.action.navigateBack).
{
    "key": "cmd+1",
    "command": "workbench.action.navigateBack",
    "when": "isMac && canNavigateBack"
},

// Cmd+2 = scroll view to top of file (Cursor Top: caret to first line, same family as Ctrl+Home on Win).
{
    "key": "cmd+2",
    "command": "cursorTop",
    "when": "editorTextFocus && isMac"
},

// Cmd+3 = scroll view to bottom of file (Cursor Bottom: caret to last line, same family as Ctrl+End on Win).
{
    "key": "cmd+3",
